package org.brightstats.stats;

import java.util.*;
import java.util.function.IntConsumer;
import org.apache.commons.math3.distribution.NormalDistribution;
import org.apache.commons.math3.linear.*;

/** Independent continuous-regressor Gaussian copula and two-stage generated-regressor OLS. */
public final class CopulaRegression {
    private CopulaRegression(){}
    public enum Method {ORIGINAL_GAUSSIAN,TWO_STAGE_GAUSSIAN}
    public enum PlottingPosition {WEIBULL,HAZEN}
    public record Model(List<String> names,int[] endogenous,Method method,PlottingPosition plottingPosition){
        public Model{names=List.copyOf(names);endogenous=endogenous.clone();Objects.requireNonNull(method);Objects.requireNonNull(plottingPosition);if(names.isEmpty()||names.size()>64||names.stream().anyMatch(name->name==null||name.isBlank())||new HashSet<>(names).size()!=names.size())throw new IllegalArgumentException("Use 1–64 uniquely named predictors.");Set<Integer> seen=new HashSet<>();for(int column:endogenous)if(column<0||column>=names.size()||!seen.add(column))throw new IllegalArgumentException("Endogenous predictor indices must be unique and in range.");if(endogenous.length==0)throw new IllegalArgumentException("Select at least one continuous endogenous predictor.");if(method==Method.TWO_STAGE_GAUSSIAN&&endogenous.length==names.size())throw new IllegalArgumentException("Two-stage Gaussian correction requires at least one exogenous regressor; otherwise choose original Gaussian correction.");}
        @Override public int[] endogenous(){return endogenous.clone();}
    }
    public record Coefficient(String name,String family,double value,Double uncorrected,Double difference){}
    public record Diagnostic(String name,int distinctValues,int tiedObservations,double skewness,double excessKurtosis,double rankScoreCorrelation,Double firstStageRSquared,double controlOnOriginalRSquared){}
    public record Fit(Model model,int observations,int residualDegreesOfFreedom,List<Coefficient> coefficients,List<Diagnostic> diagnostics,double residualSumOfSquares,double rSquared,double adjustedRSquared,double uncorrectedRSquared,double standardizedConditionNumber,double[][] generatedRegressors,double[] predictions,double[] residuals,List<String> warnings){
        public Fit{Objects.requireNonNull(model);if(observations<=model.names().size()+model.endogenous().length+1||residualDegreesOfFreedom!=observations-model.names().size()-model.endogenous().length-1||coefficients.size()!=model.names().size()+model.endogenous().length+1||diagnostics.size()!=model.endogenous().length||predictions.length!=observations||residuals.length!=observations||generatedRegressors.length!=observations||Matrices.width(generatedRegressors,3)!=model.endogenous().length)throw new IllegalArgumentException("Invalid copula result dimensions.");for(double value:new double[]{residualSumOfSquares,rSquared,adjustedRSquared,uncorrectedRSquared,standardizedConditionNumber})if(!Double.isFinite(value))throw new IllegalArgumentException("Nonfinite copula fit summary.");if(residualSumOfSquares<0||standardizedConditionNumber<1||standardizedConditionNumber>1e10||rSquared>1+1e-10||uncorrectedRSquared>1+1e-10)throw new IllegalArgumentException("Invalid copula fit summary.");for(var coefficient:coefficients)if(coefficient.name()==null||coefficient.family()==null||!Double.isFinite(coefficient.value())||coefficient.uncorrected()!=null&&!Double.isFinite(coefficient.uncorrected())||coefficient.difference()!=null&&!Double.isFinite(coefficient.difference()))throw new IllegalArgumentException("Invalid copula coefficient.");for(int i=0;i<observations;i++)if(!Double.isFinite(predictions[i])||!Double.isFinite(residuals[i]))throw new IllegalArgumentException("Nonfinite copula observation result.");coefficients=List.copyOf(coefficients);diagnostics=List.copyOf(diagnostics);generatedRegressors=Matrices.copy(generatedRegressors);predictions=predictions.clone();residuals=residuals.clone();warnings=List.copyOf(warnings);}
        @Override public double[][] generatedRegressors(){return Matrices.copy(generatedRegressors);}
        @Override public double[] predictions(){return predictions.clone();}
        @Override public double[] residuals(){return residuals.clone();}
    }
    public record Resampled(Fit point,Bootstrap.Result inference){}
    private record Scores(double[] values,int distinct,int tied){}
    private static Scores scores(double[] values,PlottingPosition position){
        int n=values.length;Integer[] order=new Integer[n];for(int i=0;i<n;i++){if(!Double.isFinite(values[i]))throw new IllegalArgumentException("Copula input must be finite.");order[i]=i;}Arrays.sort(order,Comparator.comparingDouble(index->values[index]));double[] result=new double[n];int distinct=0,tied=0;var normal=new NormalDistribution();
        for(int start=0;start<n;){Matrices.interrupted();int end=start+1;while(end<n&&values[order[start]]==values[order[end]])end++;double rank=(start+1+end)/2.0,probability=position==PlottingPosition.WEIBULL?rank/(n+1.0):(rank-.5)/n,z=normal.inverseCumulativeProbability(probability);for(int i=start;i<end;i++)result[order[i]]=z;if(end-start>1)tied+=end-start;distinct++;start=end;}
        if(distinct<3)throw new IllegalArgumentException("Copula rank transforms require at least three distinct observed values; binary/constant regressors are unsupported by this continuous method.");return new Scores(result,distinct,tied);
    }
    private static double[] column(double[][] data,int column){double[] values=new double[data.length];for(int i=0;i<data.length;i++)values[i]=data[i][column];return values;}
    private static double[] moments(double[] x,double[] z){double mx=0,mz=0;for(int i=0;i<x.length;i++){mx+=x[i]/x.length;mz+=z[i]/x.length;}double variance=0,vz=0,covariance=0;for(int i=0;i<x.length;i++){double a=x[i]-mx,b=z[i]-mz;variance+=a*a/x.length;vz+=b*b/x.length;covariance+=a*b/x.length;}double sd=Math.sqrt(variance),skew=0,kurtosis=0;for(double value:x){double scaled=(value-mx)/sd;skew+=scaled*scaled*scaled/x.length;kurtosis+=Math.pow(scaled,4)/x.length;}double correlation=covariance/(sd*Math.sqrt(vz));if(!Double.isFinite(skew)||!Double.isFinite(kurtosis)||!Double.isFinite(correlation))throw new IllegalArgumentException("Copula diagnostics exceed the finite numerical range.");return new double[]{skew,kurtosis-3,Math.max(-1,Math.min(1,correlation))};}
    private static double condition(double[][] x){double[][] standardized=new double[x.length][x[0].length+1];for(int i=0;i<x.length;i++)standardized[i][0]=1;for(int j=0;j<x[0].length;j++){double mean=0,variance=0;for(var row:x)mean+=row[j]/x.length;for(var row:x)variance+=(row[j]-mean)*(row[j]-mean)/x.length;if(!(variance>0)||!Double.isFinite(variance))throw new IllegalArgumentException("Constant or numerically unscaled copula design column.");double scale=Math.sqrt(variance);for(int i=0;i<x.length;i++)standardized[i][j+1]=(x[i][j]-mean)/scale;}var decomposition=new SingularValueDecomposition(new Array2DRowRealMatrix(standardized,false));double value=decomposition.getConditionNumber();if(decomposition.getRank()!=standardized[0].length||!Double.isFinite(value)||value>1e10)throw new IllegalArgumentException("The augmented copula design is rank deficient or numerically unidentified (standardized condition > 1e10).");return value;}
    public static Fit fit(double[][] predictors,double[] response,Model model){
        Objects.requireNonNull(model);int p=Matrices.width(predictors,3),n=predictors.length,k=model.endogenous.length;if(p!=model.names.size()||response.length!=n||n<=p+k+1)throw new IllegalArgumentException("Copula regression needs matching columns and positive augmented residual degrees of freedom.");if((long)n*(p+k+1)>5000000L)throw new IllegalArgumentException("Copula design exceeds five million cells.");var naive=OlsRegression.fit(predictors,response);List<String> warnings=new ArrayList<>();warnings.add("Continuous-regressor method: numerical storage does not establish continuity. Do not apply these formulas to categorical/ordinal or binary endogenous variables.");warnings.add("Gaussian copula and normally distributed structural-error assumptions are substantive restrictions, not verified by this fitted residual distribution. Exogenous variables must actually be exogenous.");warnings.add("Conditional OLS standard errors are intentionally omitted: generated regressors require full-procedure resampling. IID bootstrap does not establish identification or causal validity.");
        int[] exogenous=java.util.stream.IntStream.range(0,p).filter(index->Arrays.stream(model.endogenous).noneMatch(endogenous->endogenous==index)).toArray();double[][] exogenousScores=new double[n][exogenous.length];if(model.method==Method.TWO_STAGE_GAUSSIAN){for(int j=0;j<exogenous.length;j++){Matrices.interrupted();var transformed=scores(column(predictors,exogenous[j]),model.plottingPosition);for(int i=0;i<n;i++)exogenousScores[i][j]=transformed.values[i];if(transformed.tied>0)warnings.add(model.names.get(exogenous[j])+": exogenous rank scores have ties; continuous Gaussian-copula assumptions require substantive scrutiny.");}condition(exogenousScores);}else warnings.add("Original Gaussian correction requires the copula control function to be uncorrelated with exogenous controls; correlated controls can invalidate the simpler correction. Consider the two-stage method when its assumptions are appropriate.");
        double[][] controls=new double[n][k],augmented=new double[n][p+k];for(int i=0;i<n;i++)System.arraycopy(predictors[i],0,augmented[i],0,p);List<Diagnostic> diagnostics=new ArrayList<>();
        for(int j=0;j<k;j++){Matrices.interrupted();int column=model.endogenous[j];double[] original=column(predictors,column);var transformed=scores(original,model.plottingPosition);double[] values=transformed.values.clone();Double stageR2=null;if(model.method==Method.TWO_STAGE_GAUSSIAN){var first=OlsRegression.fit(exogenousScores,values);stageR2=first.rSquared();for(int i=0;i<n;i++)values[i]-=first.predict(exogenousScores[i]);}for(int i=0;i<n;i++)augmented[i][p+j]=controls[i][j]=values[i];double[] moment=moments(original,transformed.values);double overlap=OlsRegression.fit(predictors,values).rSquared();diagnostics.add(new Diagnostic(model.names.get(column),transformed.distinct,transformed.tied,moment[0],moment[1],moment[2],stageR2,overlap));if(transformed.tied>0)warnings.add(model.names.get(column)+": tied observations use average ranks; continuity cannot be assumed for genuinely discrete data.");if(overlap>.99)warnings.add(model.names.get(column)+": generated control is almost linearly explained by the original regressors (R² > .99); weak identification and unstable inference are a concern.");if(Math.abs(moment[2])>.99)warnings.add(model.names.get(column)+": the original variable and its normal scores are highly correlated. Original correction may be weakly identified; two-stage identification requires sufficiently relevant and nonnormal exogenous regressors.");}
        double condition=condition(augmented);if(condition>30)warnings.add("Augmented standardized condition number exceeds 30; this is a numerical collinearity warning, not a formal identification test.");var corrected=OlsRegression.fit(augmented,response);double[] beta=corrected.coefficients(),uncorrected=naive.coefficients();List<Coefficient> coefficients=new ArrayList<>();for(int j=0;j<beta.length;j++){boolean structural=j<=p;String name=j==0?"Intercept":j<=p?model.names.get(j-1):"Copula("+model.names.get(model.endogenous[j-p-1])+")";coefficients.add(new Coefficient(name,j==0?"Intercept":structural?"Structural":"Generated copula control",beta[j],structural?uncorrected[j]:null,structural?beta[j]-uncorrected[j]:null));}double[] predictions=new double[n],residuals=new double[n];for(int i=0;i<n;i++){predictions[i]=corrected.predict(augmented[i]);residuals[i]=response[i]-predictions[i];}return new Fit(model,n,corrected.residualDegreesOfFreedom(),coefficients,diagnostics,corrected.residualSumOfSquares(),corrected.rSquared(),corrected.adjustedRSquared(),naive.rSquared(),condition,controls,predictions,residuals,warnings);
    }
    public static Resampled bootstrap(double[][] predictors,double[] response,Model model,Bootstrap.Options options,IntConsumer progress){Fit point=fit(predictors,response,model);double[][] combined=new double[predictors.length][model.names.size()+1];for(int i=0;i<combined.length;i++){System.arraycopy(predictors[i],0,combined[i],0,model.names.size());combined[i][model.names.size()]=response[i];}List<Bootstrap.Parameter> parameters=new ArrayList<>();for(int j=0;j<point.coefficients.size();j++){var coefficient=point.coefficients.get(j);parameters.add(new Bootstrap.Parameter(coefficient.family,-1,-1,j,coefficient.name));}double[] original=point.coefficients.stream().mapToDouble(Coefficient::value).toArray();var inference=Resampling.run(combined,parameters,original,options,(sample,rows)->{double[][] x=new double[sample.length][model.names.size()];double[] y=new double[sample.length];for(int i=0;i<sample.length;i++){System.arraycopy(sample[i],0,x[i],0,model.names.size());y[i]=sample[i][model.names.size()];}return fit(x,y,model).coefficients.stream().mapToDouble(Coefficient::value).toArray();},progress,"Continuous Gaussian-copula regression ("+model.method+")","Each resample/jackknife recomputes midranks, normal scores, first-stage residuals and the augmented structural fit; no original-sample generated controls are reused.");List<String> warnings=new ArrayList<>(inference.warnings());warnings.addAll(point.warnings);inference=new Bootstrap.Result(inference.options(),inference.method(),inference.randomGenerator(),inference.signHandling(),inference.successful(),inference.failed(),inference.failures(),inference.estimates(),warnings,inference.estimator());return new Resampled(point,inference);}
}
